<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\ThemeAsset\Infrastructure\Driver\Rest;

use Psr\Http\Message\ResponseInterface;
use Psr\Http\Message\ServerRequestInterface;
use OpenApi\Attributes as OA;
use Throwable;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;
use Civi\Lughauth\Shared\Infrastructure\Sql\SqlTemplate;
use Civi\Lughauth\Features\Document\ThemeAsset\Application\Usecase\Update\ThemeAssetUpdateUsecase;
use Civi\Lughauth\Features\Document\ThemeAsset\Domain\ValueObject\ThemeAssetUidVO;
use Civi\Lughauth\Features\Document\ThemeAsset\Domain\ValueObject\ThemeAssetThemeVO;
use Civi\Lughauth\Features\Document\Theme\Domain\ThemeRef;
use Civi\Lughauth\Features\Document\ThemeAsset\Domain\ValueObject\ThemeAssetCodeVO;
use Civi\Lughauth\Features\Document\ThemeAsset\Domain\ValueObject\ThemeAssetTypeVO;
use Civi\Lughauth\Features\Document\ThemeAsset\Domain\ValueObject\ThemeAssetContentVO;
use Civi\Lughauth\Shared\Context;
use Civi\Lughauth\Shared\Security\MagicLinkService;
use Civi\Lughauth\Features\Document\ThemeAsset\Domain\ValueObject\ThemeAssetVersionVO;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Document\ThemeAsset\Application\Usecase\Update\ThemeAssetUpdateParams;
use Civi\Lughauth\Features\Document\ThemeAsset\Application\Usecase\Update\ThemeAssetUpdateResult;

class ThemeAssetUpdateController
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly SqlTemplate $sql,
        private readonly ThemeAssetUpdateUsecase $updateUsecase,
        private readonly Context $context,
        private readonly MagicLinkService $links,
    ) {
    }
    #[OA\Put(
        path: "/api/document/theme-asset/{uid}",
        tags: ["Theme asset"],
        description: "Update the value",
        parameters: [
        new OA\PathParameter(name: "uid", required: true, schema: new OA\Schema(type: "string")),
    ],
        requestBody: new OA\RequestBody(content: new OA\JsonContent(type: "object", ref:"#/components/schemas/ThemeAssetApiDTO")),
        responses: [
        new OA\Response(response: 200, description: "Ok", content: new OA\JsonContent(type: "object", ref:"#/components/schemas/ThemeAssetApiDTO")),
        new OA\Response(response: 404, description: "Not found"),
        new OA\Response(response: 409, description: "Optimist lock"),
        new OA\Response(response: 422, description: "Constraint error"),
    ]
    )
    ]
    public function update(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $this->logDebug("Update Theme asset");
        $span = $this->startSpan("Update Theme asset");
        $this->sql->begin();
        try {
            if (!isset($args['uid'])) {
                throw new NotFoundException('-');
            }
            $uid = $args['uid'];
            $value = $this->readThemeAsset($request);
            $result = $this->updateUsecase->update($uid, $value);
            $this->sql->commit();
            $value = $this->mapThemeAsset($request, $result);
            $encoded = json_encode($value);
            $response->getBody()->write($encoded === false ? '' : $encoded);
            return $response->withStatus(200)
                  ->withHeader('Content-Type', 'application/json');
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $this->sql->close();
            $span->end();
        }
    }

    private function readThemeAsset(ServerRequestInterface $request): ThemeAssetUpdateParams
    {
        $this->logDebug("Read entity for Theme asset");
        $span = $this->startSpan("Read entity for Theme asset");
        try {
            $parsed = $request->getParsedBody() ?? [];
            $body = is_array($parsed) ? $parsed : get_object_vars($parsed);
            $errorsList = new ConstraintFailList();
            $value = new ThemeAssetUpdateParams();
            $valueUid = ThemeAssetUidVO::tryFrom($body['uid'] ?? null, $errorsList);
            if (null !== $valueUid) {
                $value->uid($valueUid);
            }
            if (in_array('theme', array_keys($body))) {
                $valueTheme = ThemeAssetThemeVO::tryFrom(isset($body['theme']['$ref']) ? new ThemeRef($body['theme']['$ref']) : null, $errorsList);
                if (null !== $valueTheme) {
                    $value->theme($valueTheme);
                }
            }
            $valueCode = ThemeAssetCodeVO::tryFrom($body['code'] ?? null, $errorsList);
            if (null !== $valueCode) {
                $value->code($valueCode);
            }
            $valueType = ThemeAssetTypeVO::tryFrom($body['type'] ?? null, $errorsList);
            if (null !== $valueType) {
                $value->type($valueType);
            }
            $content = $body['content'] ?? null;
            $preffixContent = $this->context->getBaseUrl() . '/api/document/theme-asset/-/temp-content?temp=';
            if (null !== $content && strpos($content, $preffixContent) === 0) {
                $valueContent = ThemeAssetContentVO::tryFromTemporal(base64_decode(substr($content, strlen($preffixContent))), $errorsList);
                if (null !== $valueContent) {
                    $value->content($valueContent);
                }
            }
            $value->version(ThemeAssetVersionVO::tryFrom($body['version'] ?? null, $errorsList));
            if ($errorsList->hasErrors()) {
                throw $errorsList->asConstraintException();
            }
            return $value;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function mapThemeAsset(ServerRequestInterface $request, ThemeAssetUpdateResult $value): ThemeAssetApiDTO
    {
        $this->logDebug("Map entity to output dto for Theme asset");
        $span = $this->startSpan("Map entity to output dto for Theme asset");
        try {
            $theme = $value->getTheme();
            $dto = new ThemeAssetApiDTO();
            $dto->uid = $value->getUid();
            $dto->theme = $theme ? ['$ref' => $theme->uid()] : null;
            $dto->code = $value->getCode();
            $dto->type = $value->getType();
            if (null !== $value->getContent()) {
                $url = $this->context->getBaseUrl() . '/api/document/theme-asset/' . ($value->getUid() ?? '-'). '/content';
                $dto->content = $this->links->create($url, $request);
            }
            $dto->enabled = $value->isEnabled();
            $dto->version = $value->getVersion();
            return $dto;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
